import React from 'react';

export default function Sidebar({ currentSubPage, setCurrentSubPage, onLogoutClick, role = 'admin' }) {
  
  // 1️⃣ Admin Menu Items
  const adminMenuItems = [
    { name: 'Overview', icon: '🏠' },
    { name: 'Manage Teachers', icon: '🧑‍🏫' },
    { name: 'Manage Students', icon: '🧑‍🎓' },
    { name: 'Manage Subjects', icon: '📚' }, 
    { name: 'Manage Timetable', icon: '🏫' },
    { name: 'Reports', icon: '📊' },
    { name: 'Feedback', icon: '💬' },
    { name: 'Settings', icon: '⚙️' },
  ];

  // 2️⃣ Teacher Menu Items
  const teacherMenuItems = [
    { name: 'Overview', icon: '🏠' },
    { name: 'Manage Activities', icon: '🧩' },
    { name: 'Upload Materials', icon: '📂' },
    { name: 'Exams & Quizzes', icon: '📝' },
    { name: 'Student Progress', icon: '📈' },
    { name: 'Feedback', icon: '💬' },
    { name: 'Settings', icon: '⚙️' },
  ];

  // 3️⃣ Student Menu Items
  const studentMenuItems = [
    { name: 'Overview', icon: '🏠' },
    { name: 'Study Materials', icon: '📚' },
    { name: 'Lesson Activities', icon: '🧩' },
    { name: 'Exams & Quizzes', icon: '📝' },
    { name: 'Class Timetable', icon: '🗓️' },
    { name: 'Feedback', icon: '💬' },
    { name: 'Settings', icon: '⚙️' },
  ];

  // 🔄 Role එක අනුව අදාළ Menu Items Select කරගැනීම
  let menuItems = adminMenuItems;
  if (role === 'teacher') menuItems = teacherMenuItems;
  if (role === 'student') menuItems = studentMenuItems;

  return (
    <aside style={styles.sidebarContainer}>
      
      {/* 🟢 AuraPen Header / Brand Box */}
      <div style={styles.brandContainer}>
        <div style={styles.logoBadge}>🖊️</div>
        <div>
          <h2 style={styles.brandTitle}>AuraPen</h2>
          <span style={styles.roleSubtext}>{role.toUpperCase()} PORTAL</span>
        </div>
      </div>

      <hr style={styles.divider} />

      {/* 🟢 Dynamic Menu Items List */}
      <nav style={styles.menuList}>
        {menuItems.map((item) => {
          const isActive = currentSubPage === item.name;
          return (
            <button
              key={item.name}
              onClick={() => setCurrentSubPage(item.name)}
              style={{
                ...styles.menuButton,
                backgroundColor: isActive ? '#15803d' : 'transparent',
                fontWeight: isActive ? 'bold' : 'normal',
                boxShadow: isActive ? '0 4px 12px rgba(21, 128, 61, 0.35)' : 'none',
              }}
            >
              <span style={{ fontSize: '18px' }}>{item.icon}</span> 
              <span>{item.name}</span>
            </button>
          );
        })}
      </nav>

      {/* 🟢 Logout Button Section */}
      <div style={styles.logoutWrapper}>
        <button 
          onClick={onLogoutClick} 
          style={styles.logoutButton}
        >
          <span>🚪</span> Logout
        </button>
      </div>

    </aside>
  );
}

// 🎨 Clean Dark Theme Styles Matching AuraPen LMS
const styles = {
  sidebarContainer: {
    width: '260px',
    minWidth: '260px',
    height: '100vh',
    position: 'sticky',
    top: 0,
    backgroundColor: '#0f172a', // Clean Deep Dark Slate Background
    color: '#ffffff',
    display: 'flex',
    flexDirection: 'column',
    boxSizing: 'border-box',
    borderRight: '1px solid #1e293b',
    zIndex: 99,
  },
  brandContainer: {
    display: 'flex',
    alignItems: 'center',
    gap: '12px',
    padding: '20px 20px 10px 20px',
  },
  logoBadge: {
    width: '40px',
    height: '40px',
    backgroundColor: '#15803d',
    borderRadius: '10px',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    fontSize: '20px',
    boxShadow: '0 2px 8px rgba(21, 128, 61, 0.4)',
  },
  brandTitle: {
    margin: 0,
    fontSize: '20px',
    fontWeight: 'bold',
    color: '#ffffff',
  },
  roleSubtext: {
    fontSize: '10px',
    fontWeight: '700',
    color: '#4ade80',
    letterSpacing: '0.8px',
  },
  divider: {
    borderColor: '#1e293b',
    margin: '15px 20px',
    borderStyle: 'solid',
    borderWidth: '0.5px',
  },
  menuList: {
    flex: 1,
    display: 'flex',
    flexDirection: 'column',
    gap: '8px',
    padding: '0 15px',
    overflowY: 'auto',
  },
  menuButton: {
    width: '100%',
    textAlign: 'left',
    padding: '12px 18px',
    color: 'white',
    border: 'none',
    borderRadius: '10px',
    cursor: 'pointer',
    fontSize: '14.5px',
    display: 'flex',
    alignItems: 'center',
    gap: '12px',
    transition: 'all 0.2s ease',
  },
  logoutWrapper: {
    padding: '15px 15px 25px 15px',
    marginTop: 'auto',
    borderTop: '1px solid #1e293b',
  },
  logoutButton: {
    width: '100%',
    padding: '12px',
    backgroundColor: '#ef4444',
    color: 'white',
    border: 'none',
    borderRadius: '8px',
    fontWeight: 'bold',
    cursor: 'pointer',
    transition: '0.3s',
    boxShadow: '0 4px 6px rgba(239, 68, 68, 0.2)',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    gap: '8px',
  }
};
